@import 'c/ihStyles';

:host {
    display: block;
    padding-bottom: 0.75rem;
}
.actions {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 8px;
}
.result {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    margin-top: 12px;
    padding: 8px 12px;
    border-radius: 8px;
    overflow-wrap: anywhere;
}
.result_ok {
    background: var(--ih-ok-bg);
    color: var(--ih-ok-ink);
}
.result_bad {
    background: var(--ih-bad-bg);
    color: var(--ih-bad-ink);
}
.reply {
    margin-top: 6px;
    overflow-wrap: anywhere;
}
